const prep = () => {
  const dir = mkdtempSync(join(tmpdir(), 'bgsweep-'))
  cpSync(join(here, 'scripts'), join(dir, 'scripts'), { recursive: true })
  mkdirSync(join(dir, '.github'), { recursive: true })
  cpSync(join(here, '.github', 'workflows'), join(dir, '.github', 'workflows'), { recursive: true })
  cpSync(join(here, '.github', 'actions'), join(dir, '.github', 'actions'), { recursive: true })
  cpSync(join(here, 'package.json'), join(dir, 'package.json'))
  return dir
}
const guard = dir => join(dir, 'scripts', 'check-browser-gate.py')
const selfTest = dir => spawnSync('python3', [guard(dir), '--self-test'], { encoding: 'utf8', cwd: dir, maxBuffer: 64 * 1024 * 1024 })
const realTree = dir => spawnSync('python3', [guard(dir)], { encoding: 'utf8', cwd: dir, maxBuffer: 64 * 1024 * 1024 })
const failLines = out => out.match(/^FAIL .*$/gm) ?? []
const bail = (dir, msg) => { console.log(msg); if (dir) rmSync(dir, { recursive: true, force: true }); process.exit(1) }

const d0 = prep()
const c1 = selfTest(d0), c2 = realTree(d0)
console.log(`unmutated copy: self-test exit ${c1.status} (${(c1.stdout.match(/(\d+)\/(\d+) checks passed/) ?? [])[0] ?? 'no summary'}); real tree exit ${c2.status} (${(c2.stdout.match(/verdict: \w+/) ?? ['no verdict'])[0]}; ${(c2.stdout.match(/need a browser \(gated\)\s*:\s*(\d+)/) ?? [])[1] ?? '?'} browser steps read)`)
rmSync(d0, { recursive: true, force: true })
if (c1.status !== 0 || c2.status !== 0) bail(null, 'the unmutated copy is not green on both paths: nothing to sweep')

// A table that holds the same mutation twice counts it twice (found by the third review: 467 entries were 465 distinct mutants). Refuse it before anything runs.
{
  const seen = new Map()
  const note = (file, name, from, to) => { const k = [file, from, to].join('\0'); if (seen.has(k)) { console.log(`DUPLICATE  [${name}] is the same mutation of ${file} as [${seen.get(k)}]`); process.exit(1) } seen.set(k, name) }
  for (const [name, from, to] of CODE) note('check-browser-gate.py', name, from, to)
  for (const [name, from, to] of WORKFLOW) note('verify.yml', name, from, to)
  for (const [file, name, from, to] of OTHERS) note(file, name, from, to)
}
let caught = 0, total = 0, skippedByFilter = 0
const ranBy = { code: 0, verify: 0, others: 0 }
const ONLY = process.env.SWEEP_ONLY ? new RegExp(process.env.SWEEP_ONLY) : null
// SWEEP_SLICE=k/n runs the mutations whose position in the whole run (CODE, then verify.yml, then OTHERS) is k modulo n, so n processes can split the work; the n slices together are the whole run.
const SLICE = (() => { const m = /^(\d+)\/(\d+)$/.exec(process.env.SWEEP_SLICE ?? ''); if (!process.env.SWEEP_SLICE) return null; if (!m || +m[2] < 1 || +m[1] >= +m[2]) { console.log(`SWEEP_SLICE must be k/n with 0 <= k < n, not ${process.env.SWEEP_SLICE}`); process.exit(1) } return { k: +m[1], n: +m[2] } })()
let position = 0
const sweep = (kind, list, file, judge, group) => {
  for (const [name, from, to] of list) {
    const here_ = position++
    if ((ONLY && !ONLY.test(name)) || (SLICE && here_ % SLICE.n !== SLICE.k)) { skippedByFilter++; continue }
    total++
    ranBy[group]++
    const dir = prep()
    const f = join(dir, file)
    const src = readFileSync(f, 'utf8')
    const n = src.split(from).length - 1
    if (n !== 1) bail(dir, `ANCHOR  [${kind}] ${name}: the anchor occurs ${n} times, not once`)
    const out = src.replace(from, () => to)
    if (out === src) bail(dir, `NOOP    [${kind}] ${name}: the mutation changed nothing`)
    writeFileSync(f, out)
    const r = judge(dir)
    const fails = kind === 'CODE' ? failLines(r.stdout) : (/^FAIL: /m.test(r.stdout) ? ['FAIL:'] : [])
    const ok = r.status !== 0 && fails.length > 0
    if (ok) caught++
    const why = kind === 'CODE' ? failLines(r.stdout).slice(0, 2).map(l => l.slice(5, 70)).join(' | ') : ((r.stdout.match(/^  - .*$/m) ?? [''])[0].slice(4, 110))
    console.log(`${ok ? 'CAUGHT    ' : 'NOT CAUGHT'}  [${kind}] ${name}  (exit ${r.status}${why ? ': ' + why : r.stderr ? ': ' + r.stderr.split('\n').filter(Boolean).pop().slice(0, 80) : ''})`)
    rmSync(dir, { recursive: true, force: true })
  }
}
sweep('CODE', CODE, join('scripts', 'check-browser-gate.py'), selfTest, 'code')
sweep('WORKFLOW', WORKFLOW, join('.github', 'workflows', 'verify.yml'), realTree, 'verify')
for (const [file, name, from, to] of OTHERS) sweep('WORKFLOW', [[name, from, to]], file, realTree, 'others')
if (ONLY || SLICE) console.log(`\nSLICE ${[ONLY && `/${process.env.SWEEP_ONLY}/`, SLICE && `${SLICE.k}/${SLICE.n}`].filter(Boolean).join(' ')}: ran ${total} of ${total + skippedByFilter} mutations; ${skippedByFilter} were NOT run (a slice proves only what it ran)`)
console.log(`\ncaught ${caught} of ${total} mutations RUN (${ranBy.code} of the guard's code, ${ranBy.verify} of verify.yml, ${ranBy.others} of the other workflows it reads; the tables hold ${CODE.length}, ${WORKFLOW.length} and ${OTHERS.length}, all distinct); ${EXCLUDED} more were NOT run in any run, each named in this file's header as equivalent or as a crash`)
if (total === 0) { console.log('NOTHING RAN: the slice filter matched no mutation, which is not a pass'); process.exit(1) }
process.exit(caught === total ? 0 : 1)
